import{_ as o,o as a,c as r,a2 as e}from"./chunks/framework.Bi3alPNc.js";const h=JSON.parse('{"title":"循环自动化提示词：从一次失败到连续运行的 Agent 工作流","description":"> 本文由一段真实对话整理而来，经心虫（HeartFlow）判别器逐条监督后成文。适合正在搭建\\"让 Agent 自己跑起来\\"工作流的团队做内部培训。 很多人第一次尝试\\"自动化\\"时，会问一个问题：","frontmatter":{"title":"循环自动化提示词：从一次失败到连续运行的 Agent 工作流","summary":"把一段真实对话整理成可培训的 Agent 使用心得——循环自动化提示词不是一次写成的，而是部署→运行→定时任务→失败→调整→再运行的闭环，用心虫做每步的监督与决策。","author":"yun520-1","date":"2026-08-07","category":"Agent 方法论","difficulty":"进阶","aside":false,"outline":false,"skills":["心虫 HeartFlow","定时任务"],"tags":["循环自动化","提示词工程","Agent 工作流","定时任务","心虫监督"]},"headers":[],"relativePath":"cases/submissions/loop-automation-prompt/index.md","filePath":"cases/submissions/loop-automation-prompt/index.md","lastUpdated":null}'),d={name:"cases/submissions/loop-automation-prompt/index.md"};function s(l,t,n,i,u,p){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="循环自动化提示词-从一次失败到连续运行的-agent-工作流" tabindex="-1">循环自动化提示词：从一次失败到连续运行的 Agent 工作流 <a class="header-anchor" href="#循环自动化提示词-从一次失败到连续运行的-agent-工作流" aria-label="Permalink to &quot;循环自动化提示词：从一次失败到连续运行的 Agent 工作流&quot;">​</a></h1><blockquote><p>本文由一段真实对话整理而来，经心虫（HeartFlow）判别器逐条监督后成文。适合正在搭建&quot;让 Agent 自己跑起来&quot;工作流的团队做内部培训。</p></blockquote><h2 id="场景描述" tabindex="-1">场景描述 <a class="header-anchor" href="#场景描述" aria-label="Permalink to &quot;场景描述&quot;">​</a></h2><p>很多人第一次尝试&quot;自动化&quot;时，会问一个问题：</p><blockquote><p>&quot;我写一个提示词，让 Agent 每天自动跑任务，是不是就循环自动化了？&quot;</p></blockquote><p>答案是否定的。<strong>循环自动化不是一次写成的提示词</strong>，而是一个需要部署、试错、调参、最终稳定运行的工作流。这段心得来自一次真实的对话复盘：发起人想把一段讨论整理成培训材料，过程中逐步暴露了循环自动化的完整方法论。</p><h2 id="核心结论-循环自动化的五步闭环" tabindex="-1">核心结论：循环自动化的五步闭环 <a class="header-anchor" href="#核心结论-循环自动化的五步闭环" aria-label="Permalink to &quot;核心结论：循环自动化的五步闭环&quot;">​</a></h2><p>循环自动化提示词的本质，是一个<strong>自我延续的任务链</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>部署并手动运行 → 运行正常 → 设置定时任务 → 定时任务输出下一个任务计划 → 最后一步设定下一个定时任务 → 循环</span></span></code></pre></div><p>五个要点：</p><ol><li><strong>先部署、手动运行正常，再谈自动化</strong>。基础信息都没有，谈不上循环——自动化是建立在一次成功运行之上的。</li><li><strong>定时任务不是终点，而是接力棒</strong>。每个定时任务的最后一步，必须包含&quot;设定下一个定时任务&quot;的指令，否则链条断裂。</li><li><strong>失败是常态，调整是关键</strong>。最开始基本 1-2 次就会失败，要继续调整。能连续正常运行 3 次，基本可以判定这个提示词成功了。</li><li><strong>从 500 字开始，逐步增加到 1000 字</strong>。超过 500 字、任务拆分 10 行以上是起步线；&quot;啥时候把这个项目的提示词增加到 1000 字，说明项目离成功不远了&quot;。</li><li><strong>永远没有一句话就能用的提示词</strong>。任何提示词都要经过&quot;运行→失败→调整→再运行&quot;的迭代。</li></ol><h2 id="详细程度与成功率的关系-心虫补全边界" tabindex="-1">详细程度与成功率的关系（心虫补全边界） <a class="header-anchor" href="#详细程度与成功率的关系-心虫补全边界" aria-label="Permalink to &quot;详细程度与成功率的关系（心虫补全边界）&quot;">​</a></h2><p>对话中有一句反问：&quot;提示词越多，成功率越高是吗？&quot;</p><p><strong>心虫判别后补充的边界</strong>：详尽程度与成功率<strong>正相关，但有上限</strong>。详细提示词（500-1000 字、10 行以上任务拆解）确实显著提升成功率，因为：</p><ul><li>明确了任务边界，Agent 不需要猜测意图；</li><li>拆解成子任务后，每个环节可独立验证；</li><li>写了验收标准，Agent 知道&quot;什么算完成&quot;。</li></ul><p>但<strong>冗余指令会稀释注意力</strong>——与任务无关的细节、重复的约束、互相矛盾的优先级，反而降低成功率。正确做法是：<strong>每一条指令都要能回答&quot;它帮助 Agent 更准了吗&quot;，答不出就删掉</strong>。</p><h2 id="任务性质决定思维模型-注意力权重的调整" tabindex="-1">任务性质决定思维模型：注意力权重的调整 <a class="header-anchor" href="#任务性质决定思维模型-注意力权重的调整" aria-label="Permalink to &quot;任务性质决定思维模型：注意力权重的调整&quot;">​</a></h2><p>对话中的关键洞见：</p><blockquote><p>&quot;看起来像根据任务性质，然后通过对应任务的思维模型对模型的注意力权重调整，然后再让 agent 去执行。&quot;</p></blockquote><p>这句话拆开是三件事：</p><table tabindex="0"><thead><tr><th>层次</th><th>含义</th><th>示例</th></tr></thead><tbody><tr><td>任务性质</td><td>判断任务属于哪一类</td><td>信息收集 / 数据分析 / 内容生成 / 流程执行</td></tr><tr><td>思维模型</td><td>为该类任务选择合适的思考框架</td><td>分析类用 SWOT、决策类用决策矩阵、创作类用结构化大纲</td></tr><tr><td>注意力权重</td><td>让模型把&quot;注意力&quot;集中到关键环节</td><td>分析任务强调&quot;先列下行风险&quot;、生成任务强调&quot;先列结构再填充&quot;</td></tr></tbody></table><p><strong>心虫的定位正是这个&quot;判定器&quot;</strong>——它是 AGI 五层架构的第一层（辨别层），不生成、不推理，只判别已有的东西对不对。在循环自动化里，心虫做的是：</p><ul><li><strong>输入侧</strong>：判别任务类型是否匹配所选思维模型；</li><li><strong>执行侧</strong>：监督每个环节的产出是否达标（有无过度自信、有无矛盾、有无模糊）；</li><li><strong>输出侧</strong>：门禁拦截——检测到仇恨、操控、虚假声明、无依据断言时，直接 block/rewrite/verify，不让错误内容流向下游。</li></ul><p>一句话：<strong>任务性质决定思维模型，思维模型决定注意力分配，心虫监督整个过程</strong>。</p><h2 id="更新日志不是形式-和技能、知识库联动" tabindex="-1">更新日志不是形式：和技能、知识库联动 <a class="header-anchor" href="#更新日志不是形式-和技能、知识库联动" aria-label="Permalink to &quot;更新日志不是形式：和技能、知识库联动&quot;">​</a></h2><p>对话中反思：</p><blockquote><p>&quot;我只是强制完成更新日志，确实应该和技能、知识库联系起来。&quot;</p></blockquote><p>这是个重要教训。<strong>强制完成更新日志 ≠ 自动化闭环</strong>。更新日志的价值在于：</p><ol><li>记录这次运行<strong>改了什么</strong>（对比上一次）；</li><li>沉淀<strong>成功/失败模式</strong>到技能库（下次同类任务直接调用）；</li><li>把经验<strong>蒸馏进知识库</strong>（让 Agent 的上下文越来越准）。</li></ol><p>循环自动化的正确姿势是：每次运行结束，Agent 应该<strong>更新日志 + 把新学到的模式写入技能/知识库</strong>，这样下一次运行是基于更丰富的上下文，而不是从零开始。</p><h2 id="关于比喻-任何比喻都会错位" tabindex="-1">关于比喻：任何比喻都会错位 <a class="header-anchor" href="#关于比喻-任何比喻都会错位" aria-label="Permalink to &quot;关于比喻：任何比喻都会错位&quot;">​</a></h2><p>对话中有一个生动的比喻：</p><blockquote><p>&quot;砍树是任务，而砍树的斧子是工具，挥动斧头砍树是 skills。而不断挥舞斧子的手臂肌肉就是力量。肌肉力量通过不断挥舞斧头从而不断强化。而为什么使用斧子砍树而不是用手就是每个人看东西的角度不一样所采取的策略也不样。&quot;</p></blockquote><p>但紧接着是一句更重要的自我纠正：</p><blockquote><p>&quot;不用比喻，任何比喻都会错位。&quot;</p></blockquote><p><strong>心虫监督后的处理</strong>：比喻可以帮助初学者建立直觉，但<strong>不能替代对概念本身的精确定义</strong>。培训材料里，比喻只作为引导出现一次，随后立即给出准确术语：</p><table tabindex="0"><thead><tr><th>比喻</th><th>准确术语</th></tr></thead><tbody><tr><td>砍树</td><td>任务（Task）——要达成的目标</td></tr><tr><td>斧子</td><td>工具（Tool）——完成任务的手段</td></tr><tr><td>挥动斧头</td><td>技能（Skill）——调用工具完成动作的流程</td></tr><tr><td>手臂肌肉</td><td>能力（Capability）——通过反复执行不断强化的系统能力</td></tr><tr><td>为什么用斧子不用手</td><td>策略（Strategy）——不同视角下对同一任务的不同路径选择</td></tr></tbody></table><h2 id="心虫监督决策记录" tabindex="-1">心虫监督决策记录 <a class="header-anchor" href="#心虫监督决策记录" aria-label="Permalink to &quot;心虫监督决策记录&quot;">​</a></h2><p>本文 10 条核心论断全部经过心虫 <code>checkOutput</code> 判别，结果：</p><table tabindex="0"><thead><tr><th>论断</th><th>判别结果</th></tr></thead><tbody><tr><td>循环自动化的核心是定时任务接力闭环</td><td>✅ pass</td></tr><tr><td>没有一句话就能用的提示词</td><td>✅ pass</td></tr><tr><td>连续运行 3 次判定成功</td><td>✅ pass</td></tr><tr><td>500 字 / 10 行是起步线</td><td>✅ pass</td></tr><tr><td>提示词越详细成功率越高</td><td>⚠️ pass（需补边界：正相关但有上限）</td></tr><tr><td>任务性质决定思维模型和注意力权重</td><td>✅ pass</td></tr><tr><td>心虫是 AGI 第一层辨别引擎</td><td>✅ pass</td></tr><tr><td>砍树比喻（任务/工具/技能/力量）</td><td>✅ pass</td></tr><tr><td>任何比喻都会错位</td><td>✅ pass</td></tr><tr><td>更新日志应与技能、知识库联动</td><td>✅ pass</td></tr></tbody></table><p>心虫监督的价值：<strong>它不会因为&quot;这段话写得漂亮&quot;就放行</strong>——它逐条检查证据充分性、矛盾、模糊和过度自信。这正是循环自动化里最需要的&quot;判别者&quot;：AI 能产生无限，但需要有人说不。</p><h2 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h2><ol><li>读者能复述循环自动化的五步闭环（部署→运行→定时→计划→再定时）。</li><li>读者知道&quot;连续运行 3 次&quot;是提示词成功的基本判据。</li><li>读者理解&quot;任务性质→思维模型→注意力权重→Agent 执行&quot;的链路。</li><li>读者能把更新日志和技能/知识库联动，而不是流于形式。</li><li>读者理解比喻的局限，能切换到准确术语。</li></ol>',43)])])}const q=o(d,[["render",s]]);export{h as __pageData,q as default};
